def prepare_docx_conversion(directory="."):
    """Write this registered skill's fixed assets into an authorized execution directory."""
    import base64
    from pathlib import Path
    import shutil
    import tempfile

    parent = Path(directory).resolve(strict=True)
    root = Path(tempfile.mkdtemp(prefix=".docx-profile-", dir=parent))
    try:
        for name, encoded in _DOCX_ASSETS.items():
            target = root / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(base64.b64decode(encoded, validate=True))
    except BaseException:
        shutil.rmtree(root, ignore_errors=True)
        raise
    return {
        "script_path": str(root / "scripts/convert.py"),
        "reference_path": str(root / "assets/reference.docx"),
        "workflow_directory": str(root),
    }
